1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  Message,
6	  MessageChunk,
7	  SendMessageParams,
8	  ToolCall,
9	  ToolResultContent,
10	  UsageMetadata,
11	} from '../types/ai.js';
12	import type {OutgoingMessage} from '../types/messages.js';
13	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
14	import type {SessionStore} from '../types/sessionStore.js';
15	import {toMessages, createContextConfig} from './conversationContext.js';
16	import type {ContextConfig} from './conversationContext.js';
17	import {
18	  shouldContinueToolLoop,
19	  collectText,
20	  buildToolCallMessages,
21	  collectToolCalls,
22	  extractStopReason,
23	  extractUsage,
24	} from './orchestratorHelpers.js';
25	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
26	import {log} from '../shared/logger.js';
27	
28	const DEFAULT_MAX_TOOL_ROUNDS = 5;
29	
30	export interface OrchestratorHooks {
31	  beforeSession?: (session: ChatSession) => Promise<void>;
32	  afterSession?: (session: ChatSession) => Promise<void>;
33	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
34	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
35	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
36	  afterModelResponse?: (session: ChatSession, responseText: string, usage?: UsageMetadata) => Promise<void>;
37	  onError?: (session: ChatSession, error: Error) => Promise<void>;
38	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
39	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
40	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
41	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
42	}
43	
44	export interface ToolBudgetInfo {
45	  maxToolRounds: number;
46	  requestedTools: string[];
47	}
48	
49	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
50	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
51	
52	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
53	
54	export interface ChatOrchestrator {
55	  processMessage(session: ChatSession): Promise<string>;
56	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
57	}
58	
59	export interface ChatOrchestratorOptions {
60	  maxToolRounds?: number;
61	  contextConfig?: Partial<ContextConfig>;
62	  promptBuilderOptions?: PromptBuilderOptions;
63	  hooks?: OrchestratorHooks;
64	  sessionStore?: SessionStore;
65	}
66	
67	interface ToolExecutionResult {
68	  clientMessages: OutgoingMessage[];
69	  suppressOutput: boolean;
70	}
71	export function createChatOrchestrator(
72	  provider: AIProvider,
73	  promptBuilder: PromptBuilder,
74	  toolRegistry?: ToolRegistry,
75	  options?: ChatOrchestratorOptions
76	): ChatOrchestrator {
77	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
78	  const contextConfig = createContextConfig(options?.contextConfig);
79	  const toolInstructions = toolRegistry?.getPromptInstructions();
80	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
81	  const tools = toolRegistry?.getDefinitions();
82	  const hooks = options?.hooks;
83	  const sessionStore = options?.sessionStore;
84	
85	  return {
86	    async processMessage(session: ChatSession): Promise<string> {
87	      return collectText(this.processMessageStream(session));
88	    },
89	
90	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
91	      if (hooks?.beforeSession) await hooks.beforeSession(session);
92	
93	      try {
94	        let userMessage = lastUserContent(session);
95	
96	        if (hooks?.beforeUserInput) {
97	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
98	        }
99	
100	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
101	
102	        const systemPrompt = hooks?.beforeModelResponse
103	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
104	          : baseSystemPrompt;
105	
106	        const messages: Message[] = toMessages(session.entries, contextConfig);
107	        let lastUsage: UsageMetadata | undefined;
108	        let responseText = '';
109	
110	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
111	        for (let round = 0; ; round++) {
112	          log.info('orchestrator', 'starting round', {round});
113	          const pendingToolCalls: ToolCall[] = [];
114	
115	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
116	          responseText += outcome.text;
117	          lastUsage = outcome.usage ?? lastUsage;
118	
119	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
120	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
121	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
122	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
123	            break;
124	          }
125	
126	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
127	          const {clientMessages, suppressOutput} = await executeToolCalls(
128	            pendingToolCalls,
129	            messages,
130	            session,
131	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
132	          );
133	          log.info('orchestrator', 'tool execution complete', {
134	            clientMessageCount: clientMessages.length,
135	            clientMessageTypes: clientMessages.map(m => m.type),
136	            suppressOutput,
137	          });
138	
139	          if (clientMessages.length > 0) {
140	            yield {type: 'tool_result' as const, clientMessages};
141	          }
142	
143	          if (suppressOutput) {
144	            yield {type: 'suppress_output' as const};
145	          }
146	        }
147	
148	        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, lastUsage);
149	      } catch (error) {
150	        if (hooks?.onError && error instanceof Error) {
151	          await hooks.onError(session, error);
152	        }
153	        throw error;
154	      } finally {
155	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
156	        commitStreamingEntries(session);
157	        try {
158	          if (hooks?.afterSession) await hooks.afterSession(session);
159	        } finally {
160	          await saveSession(sessionStore, session);
161	        }
162	      }
163	    },
164	  };
165	}
166	
167	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
168	function normalizeToolRounds(value: number | undefined): number {
169	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
170	  return Math.max(0, Math.floor(value));
171	}
172	
173	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
174	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
175	  if (round < maxToolRounds) return false;
176	  log.warn('orchestrator', 'tool budget exhausted', {
177	    maxToolRounds,
178	    requestedTools: pendingToolCalls.map(tc => tc.name),
179	  });
180	  return true;
181	}
182	
183	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
184	async function* closeExhaustedTurn(
185	  session: ChatSession,
186	  budget: ToolBudgetInfo,
187	  hook?: OnToolBudgetExhausted
188	): AsyncGenerator<MessageChunk, string> {
189	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
190	  if (sentence !== '') yield {type: 'text', text: sentence};
191	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
192	  return sentence;
193	}
194	
195	interface RoundOutcome {
196	  stopReason: string;
197	  text: string;
198	  usage?: UsageMetadata;
199	}
200	
201	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
202	async function* streamRound(
203	  provider: AIProvider,
204	  request: SendMessageParams,
205	  pendingToolCalls: ToolCall[]
206	): AsyncGenerator<MessageChunk, RoundOutcome> {
207	  let stopReason = '';
208	  let text = '';
209	  let usage: UsageMetadata | undefined;
210	
211	  for await (const chunk of provider.sendMessage(request)) {
212	    yield chunk;
213	    collectToolCalls(chunk, pendingToolCalls);
214	    stopReason = extractStopReason(chunk) ?? stopReason;
215	    usage = extractUsage(chunk) ?? usage;
216	    if (chunk.type === 'text') text += chunk.text;
217	  }
218	
219	  return {stopReason, text, usage};
220	}
221	
222	// A changed message is also written back to the session's last user entry.
223	async function rewriteUserMessage(
224	  session: ChatSession,
225	  userMessage: string,
226	  hook: (session: ChatSession, userMessage: string) => Promise<string>
227	): Promise<string> {
228	  const modified = await hook(session, userMessage);
229	  if (modified === userMessage) return userMessage;
230	
231	  updateLastUserContent(session, modified);
232	  return modified;
233	}
234	
235	function lastUserContent(session: ChatSession): string {
236	  for (let i = session.entries.length - 1; i >= 0; i--) {
237	    const entry = session.entries[i];
238	    if (entry.role === 'user') return entry.content;
239	  }
240	  return '';
241	}
242	
243	function updateLastUserContent(session: ChatSession, content: string): void {
244	  for (let i = session.entries.length - 1; i >= 0; i--) {
245	    const entry = session.entries[i];
246	    if (entry.role === 'user') {
247	      entry.content = content;
248	      return;
249	    }
250	  }
251	}
252	
253	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
254	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
255	  const context: ToolContext = {
256	    userId: session.userId,
257	    sessionId: session.sessionId,
258	    workspaceId: session.workspaceId,
259	    authHeaders: session.authHeaders,
260	  };
261	
262	  return async (tc: ToolCall): Promise<ToolResponse> => {
263	    const declined =
264	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
265	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
266	  };
267	}
268	
269	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
270	async function consultPolicy(
271	  policy: BeforeToolCall,
272	  session: ChatSession,
273	  tc: ToolCall
274	): Promise<ToolResponse | undefined> {
275	  try {
276	    return await policy(session, tc);
277	  } catch (error) {
278	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
279	      tool: tc.name,
280	      errorType: error instanceof Error ? error.name : typeof error,
281	    });
282	    return {result: `The ${tc.name} call was declined and not performed.`};
283	  }
284	}
285	
286	async function executeToolCalls(
287	  pendingToolCalls: ToolCall[],
288	  messages: Message[],
289	  session: ChatSession,
290	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
291	): Promise<ToolExecutionResult> {
292	  messages.push(buildToolCallMessages(pendingToolCalls));
293	
294	  const responses = await Promise.all(
295	    pendingToolCalls.map(async tc => {
296	      const response = await runToolCall(tc);
297	      return {tc, response};
298	    })
299	  );
300	
301	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
302	    type: 'tool_result' as const,
303	    toolUseId: tc.id,
304	    content: response.result,
305	  }));
306	  messages.push({role: 'user', content: toolResults});
307	
308	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
309	
310	  return {
311	    clientMessages: assignEntryIndices(rawClientMessages, session),
312	    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
313	  };
314	}
315	
316	function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
317	  return clientMessages.map(msg => {
318	    if (msg.type !== 'entry_upsert') return msg;
319	    const index = appendEntry(session, msg.entry);
320	    return {...msg, index};
321	  });
322	}
323	
324	// A store outage is not a reason to fail the turn the customer already received.
325	async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
326	  if (!store?.save) return;
327	
328	  try {
329	    await store.save(session);
330	  } catch (error) {
331	    const message = error instanceof Error ? error.message : String(error);
332	    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
333	  }
334	}
